// 5. СПРАВОЧНИКИ (ДЛЯ ВЫПАДАЮЩИХ СПИСКОВ В UI)
// ============================================================================
func (q *Queries) ListSettlementsByCommunity(ctx context.Context, communityID int64) ([]ListSettlementsByCommunityRow, error) {
	rows, err := q.db.QueryContext(ctx, listSettlementsByCommunity, communityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSettlementsByCommunityRow
	for rows.Next() {
		var i ListSettlementsByCommunityRow
		if err := rows.Scan(&i.ID, &i.Name, &i.Type); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
